@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Poppins:wght@300;400;500;600;700&display=swap');


:root{

    --black:#0b0b0b;
    --black2:#151515;
    --white:#ffffff;
    --gold:#d4af37;
    --gray:#9d9d9d;

    --transition:.4s ease;
    --radius:12px;

}



*{
    margin:0;
    padding:0;
    box-sizing:border-box;
}

html{
    scroll-behavior:smooth;
    scroll-padding-top:calc(var(--header-height, 100px) + 24px);
}

body{

    font-family:'Poppins',sans-serif;
    background:var(--black);
    color:var(--white);
    overflow-x:hidden;

}

img{
    width:100%;
    display:block;
}

a{
    text-decoration:none;
    color:inherit;
}

ul{
    list-style:none;
}

section{
    padding:100px 8%;
}

h1,h2,h3,h4,h5{
    font-weight:500;
}

/*==========================================
    HEADER
==========================================*/

header{

    position:fixed;
    top:0;
    left:0;

    width:100%;

    padding:20px 8%;

    display:flex;
    justify-content:space-between;
    align-items:center;

    background:rgba(0,0,0,.45);

    backdrop-filter:blur(12px);

    transition:.35s ease;

    z-index:1000;

}

.logo h2{

    font-family:'Bebas Neue',sans-serif;

    font-size:40px;

    letter-spacing:2px;

    color:#fff;

}

nav ul{

    display:flex;

    align-items:center;

    gap:38px;

}

nav ul li a::after{

    content:"";

    position:absolute;

    left:0;

    bottom:-8px;

    width:0;

    height:2px;

    background:var(--gold);

    transition:.35s;

}

nav ul li a:hover::after,

nav ul li a.active::after{

    width:100%;

}

nav ul li a.active{

    color:var(--gold);

}

nav ul li a{

    position:relative;

    font-size:15px;

    color:#ddd;

    font-weight:500;

    transition:.35s;

}

nav ul li a:hover{

    color:var(--gold);

}

.btn{

    display:inline-flex;

    justify-content:center;

    align-items:center;

    padding:13px 30px;

    border:2px solid var(--gold);

    border-radius:40px;

    color:var(--gold);

    font-weight:600;

    transition:.35s;

}

.btn:hover{

    background:var(--gold);

    color:#000;

}

/*================ MENU TOGGLE ================*/

.menu-toggle{

    display:none;

    width:34px;
    padding:0;
    border:0;
    background:transparent;

    cursor:pointer;

}

.menu-toggle span{

    display:block;

    width:100%;

    height:3px;

    margin:7px 0;

    background:#fff;

    transition:.35s;

}

/*=========================================================
    NAVBAR RESPONSIVE
=========================================================*/

/*========== Sticky Header ==========*/

header.scrolled{

    padding:14px 8%;

    background:rgba(8,8,8,.95);

    box-shadow:0 8px 25px rgba(0,0,0,.35);

}

/*========== Large Tablet ==========*/

@media(max-width:992px){

    header{backdrop-filter:none; -webkit-backdrop-filter:none;}

    .menu-toggle{

        display:block;

        z-index:2001;

    }

    header > .btn{

        display:none;

    }

    nav{

        position:fixed;

        top:0;

        right:0;
        transform:translateX(100%);
        visibility:hidden;

        width:min(320px, 88vw);
        padding:100px 24px 32px;
        overflow-y:auto;

        height:100vh;
        height:100dvh;

        background:#0d0d0d;

        display:flex;

        justify-content:center;

        align-items:center;

        transition:.45s ease;

        z-index:2000;

        border-left:1px solid rgba(255,255,255,.08);

    }

    nav.active{

        transform:translateX(0);
        visibility:visible;

    }

    nav ul{

        flex-direction:column;

        gap:35px;

    }

    nav ul li a{

        font-size:22px;

    }

}

/*========== Mobile ==========*/

@media(max-width:576px){

    header{

        padding:18px 6%;

    }

    .logo h2{

        font-size:32px;

    }

}

/*========== Hamburger Animation ==========*/

.menu-toggle.active span:nth-child(1){

    transform:translateY(10px) rotate(45deg);

}

.menu-toggle.active span:nth-child(2){

    opacity:0;

}

.menu-toggle.active span:nth-child(3){

    transform:translateY(-10px) rotate(-45deg);

}

body.menu-open{

    position:fixed;
    width:100%;
    overflow:hidden;

}

/*=========================================================
    NAVBAR FINAL POLISH
=========================================================*/

/*========== Background Overlay ==========*/

.nav-overlay{

    position:fixed;

    inset:0;

    background:rgba(0,0,0,.65);

    backdrop-filter:blur(4px);

    opacity:0;

    visibility:hidden;

    transition:.35s;

    z-index:999;

}

.nav-overlay.active{

    opacity:1;

    visibility:visible;

}

/*========== Menu Item Animation ==========*/

@media(max-width:992px){

    nav ul li{

        opacity:0;

        transform:translateX(40px);

        transition:.45s;

    }

    nav.active ul li{

        opacity:1;

        transform:translateX(0);

    }

    nav.active ul li:nth-child(1){

        transition-delay:.08s;

    }

    nav.active ul li:nth-child(2){

        transition-delay:.16s;

    }

    nav.active ul li:nth-child(3){

        transition-delay:.24s;

    }

    nav.active ul li:nth-child(4){

        transition-delay:.32s;

    }

    nav.active ul li:nth-child(5){

        transition-delay:.40s;

    }

}

/* Hero grows with its content; padding reserves the fixed header and indicator. */
.hero{
    position:relative;
    min-height:100vh;
    min-height:100svh;
    display:flex;
    align-items:center;
    justify-content:center;
    padding:calc(var(--header-height, 100px) + 40px) 8% 115px;
    text-align:center;
    background:linear-gradient(rgba(0,0,0,.65),rgba(0,0,0,.75)),url("images/hero.jpg") center/cover;
    background-attachment:fixed;
}
.hero-content{position:relative; z-index:2; width:100%; max-width:900px; min-width:0;}
.hero-content .hero-tag{color:var(--gold); letter-spacing:5px; margin-bottom:20px; font-size:14px;}
.hero-content h1{font-family:'Bebas Neue',sans-serif; font-size:105px; line-height:.96; letter-spacing:3px; margin-bottom:15px;}
.hero-content h2{font-size:34px; font-weight:300; color:#ddd; margin-bottom:30px; letter-spacing:4px;}
.hero-content .hero-description{width:100%; max-width:700px; margin:0 auto; font-size:18px; line-height:1.9; color:#cfcfcf; letter-spacing:normal;}
.hero-stats{display:flex; justify-content:center; gap:70px; margin-top:40px;}
.hero-stats h3{font-size:48px; color:var(--gold); margin-bottom:5px;}
.hero-stats span{font-size:15px; color:#bbb; letter-spacing:2px;}
@media(max-width:1100px){
    .hero-content h1{font-size:70px; line-height:1.07;}
    header{padding-left:5%; padding-right:5%;}
    nav ul{gap:24px;}
}
@media(max-width:768px){
    .hero{align-items:flex-start; background-attachment:scroll; padding:calc(var(--header-height, 90px) + 32px) 6% 110px;}
    .hero-content h1{font-size:50px; line-height:1.1;}
    .hero-content h2{font-size:22px; letter-spacing:2px;}
    .hero-content .hero-description{font-size:16px; line-height:1.8;}
    .hero-stats{gap:30px; flex-wrap:wrap; margin-top:32px;}
}
@media(max-width:500px){
    .hero-content h1{font-size:38px; letter-spacing:1px;}
    .hero-content h2{font-size:18px; letter-spacing:1px;}
    .hero-content .hero-tag{font-size:11px; letter-spacing:3px;}
    .hero-content .hero-description{font-size:14px; line-height:1.7;}
    .hero-stats{gap:24px;}
    .hero-stats h3{font-size:36px;}
}

/*==========================================
    HERO
==========================================*/

.overlay{

    position:absolute;

    inset:0;

    background:rgba(0,0,0,.65);

}

.buttons{

    margin-top:45px;

    display:flex;

    justify-content:center;

    gap:20px;

}

.primary-btn{

    padding:15px 40px;

    background:var(--gold);

    color:#000;

    border-radius:40px;

    transition:.4s;

    font-weight:600;

}

.primary-btn:hover{

    transform:translateY(-5px);

}

.secondary-btn{

    padding:15px 40px;

    border:2px solid white;

    border-radius:40px;

    transition:.4s;

}

.secondary-btn:hover{

    background:white;

    color:black;

}

/*==========================================
    ABOUT
==========================================*/

.about{

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:70px;

    align-items:center;

}

.about .left img{

    border-radius:15px;

}

.right h5{

    color:var(--gold);

    letter-spacing:4px;

    margin-bottom:15px;

}

.right h2{

    font-family:'Bebas Neue';

    font-size:55px;

    line-height:60px;

    margin-bottom:25px;

}

.right p{

    color:#bdbdbd;

    line-height:1.8;

    margin-bottom:40px;

}

.stats{

    display:flex;

    gap:50px;

}

.stats div{

    text-align:center;

}

.stats h3{

    font-size:48px;

    color:var(--gold);

    margin-bottom:10px;

}

.stats p{

    margin:0;

    color:#ccc;

}

/*==========================================
    COMMON TITLES
==========================================*/

section h5{

    color:var(--gold);

    letter-spacing:4px;

    margin-bottom:12px;

}

.section-heading{
    text-align:center;
    margin-bottom:70px;
}
.section-heading .section-tag{
    display:inline-block;
    color:var(--gold);
    letter-spacing:4px;
    font-size:14px;
    margin-bottom:15px;
}
.section-heading h2{
    font-size:52px;
    color:#fff;
}

section h2{

    font-family:'Bebas Neue';

    font-size:60px;

    margin-bottom:45px;

}

/*==========================================
    END OF PART 1
    PART 2 STARTS BELOW THIS
==========================================*/

/*==========================================
    SERVICES
==========================================*/

/* Studio components: shared by the redesigned sections only. */
.studio-section{color:#f4f0e7; padding:100px 8%;}
.studio-heading{display:flex; justify-content:space-between; align-items:flex-end; gap:40px; margin-bottom:48px;}
.studio-kicker{display:block; color:var(--gold); font-size:11px; font-weight:500; letter-spacing:2.5px; line-height:1.6;}
.studio-heading h2{font-family:'Bebas Neue',sans-serif; font-size:clamp(44px,5vw,72px); line-height:1.02; letter-spacing:1px; margin:16px 0 0;}
.studio-heading > p{max-width:390px; color:#c6c3bb; font-size:15px; line-height:1.9;}
.studio-grid{display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:28px;}
.studio-card{display:flex; flex-direction:column; min-width:0; background:#171717; border:1px solid #343129; border-radius:6px; overflow:hidden; transition:border-color .3s,box-shadow .3s;}
.studio-card-image{aspect-ratio:16/9; overflow:hidden; background:#202020;}
.studio-card-image img{height:100%; object-fit:cover;}
.studio-card-body{display:flex; flex-direction:column; flex:1; padding:28px;}
.studio-card h3{font-family:'Bebas Neue',sans-serif; font-size:34px; line-height:1.1; letter-spacing:.5px; margin:14px 0;}
.studio-card p{color:#c6c3bb; font-size:14px; line-height:1.85; margin-bottom:28px;}
.text-link{display:inline-flex; align-items:center; gap:20px; color:#e2c263; font-size:13px; font-weight:500; padding:10px 0; width:fit-content; margin-top:auto; border-bottom:1px solid #756330; transition:color .25s,border-color .25s;}
.text-link span{font-size:20px; line-height:1;}
.text-link:hover{color:#fff3c3; border-color:#fff3c3;}
.studio-card:focus-within{border-color:var(--gold);}
a:focus-visible,button:focus-visible{outline:2px solid #efcf75; outline-offset:5px;}
@media(hover:hover) and (pointer:fine){.studio-card:hover{border-color:#a58b40; box-shadow:0 16px 40px #0004;}}
.services.studio-section{background:linear-gradient(145deg,#141414,#0d0d0d); text-align:left; opacity:1; transform:none;}

/* Home service showcase: native disclosures work with touch, keyboard and without JS. */
.services [data-service-showcase] .studio-card-image{position:relative;}
.showcase-frame{height:100%; transform:scale(1); transition:transform .45s ease;}
.services [data-service-showcase] .studio-card-image::after{
    content:"";
    position:absolute;
    inset:auto 0 0;
    height:3px;
    background:var(--gold);
    transform:scaleX(.18);
    transform-origin:left;
    transition:transform .4s ease;
}
.showcase-disclosure{margin:0 0 20px; border-block:1px solid #48402d;}
.showcase-disclosure summary{
    display:flex;
    justify-content:space-between;
    align-items:center;
    gap:16px;
    min-height:48px;
    padding:12px 0;
    color:#e2c263;
    font-size:13px;
    line-height:1.6;
    cursor:pointer;
    list-style:none;
}
.showcase-disclosure summary::-webkit-details-marker{display:none;}
.showcase-disclosure summary:focus-visible{outline:2px solid #efcf75; outline-offset:4px;}
.showcase-disclosure summary svg{width:20px; height:20px; flex-shrink:0; fill:none; stroke:currentColor; stroke-width:1.5; transition:transform .25s;}
.showcase-disclosure[open] summary svg{transform:rotate(180deg);}
.showcase-detail{padding:6px 0 22px;}
.showcase-detail .studio-kicker{font-size:10px; letter-spacing:1.5px; margin-bottom:10px;}
.studio-card .showcase-detail p{font-size:13px; margin:0;}
.showcase-disclosure[open] .showcase-detail{animation:showcase-reveal .28s ease-out;}
.services [data-service-showcase] .studio-card-body > p{margin-bottom:0;}
.services [data-service-showcase]:has(details[open]){border-color:#a58b40;}
.services [data-service-showcase]:has(details[open]) .showcase-frame{transform:scale(1.035);}
.services [data-service-showcase]:has(details[open]) .studio-card-image::after{transform:scaleX(1);}
@media(hover:hover) and (pointer:fine){
    .services [data-service-showcase]:hover .showcase-frame{transform:scale(1.035);}
    .services [data-service-showcase]:hover .studio-card-image::after{transform:scaleX(1);}
}
@keyframes showcase-reveal{
    from{opacity:0; transform:translateY(6px);}
    to{opacity:1; transform:translateY(0);}
}
@media(max-width:1100px){.studio-section{padding:90px 6%;}.studio-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:768px){.studio-section{padding:72px 6%;}.studio-heading{display:block; margin-bottom:32px;}.studio-heading > p{margin-top:22px;}.studio-grid{grid-template-columns:1fr; gap:24px;}.studio-card-body{padding:26px;}}


/*==========================================
    PORTFOLIO
==========================================*/

.portfolio{
    background:var(--black);
    text-align:center;
}

.gallery{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    gap:25px;
    margin-top:60px;
}

.item{
    overflow:hidden;
    border-radius:15px;
    position:relative;
}

.item img{
    height:320px;
    object-fit:cover;
    transition:.6s;
}

.item::before{
    content:'';
    position:absolute;
    inset:0;
    background:rgba(0,0,0,.35);
    opacity:0;
    transition:.4s;
    z-index:1;
}

.item:hover::before{
    opacity:1;
}

.item:hover img{
    transform:scale(1.12);
}

/*==========================================
    CTA
==========================================*/

.cta{
    text-align:center;
    background:linear-gradient(135deg,#111,#1d1d1d);
}

.cta h2{
    margin-bottom:35px;
    font-size:65px;
}

/*==========================================
    FOOTER
==========================================*/

footer{
    padding:60px 8%;
    text-align:center;
    background:#050505;
    border-top:1px solid rgba(255,255,255,.08);
}

footer h2{
    font-family:'Bebas Neue',sans-serif;
    font-size:42px;
    margin-bottom:15px;
}

footer p{
    color:#999;
    line-height:1.8;
    margin-bottom:10px;
}

/*==========================================
    SCROLLBAR
==========================================*/

::-webkit-scrollbar{
    width:8px;
}

::-webkit-scrollbar-track{
    background:#111;
}

::-webkit-scrollbar-thumb{
    background:var(--gold);
    border-radius:20px;
}

/*==========================================
    SELECTION
==========================================*/

::selection{
    background:var(--gold);
    color:#000;
}

/*==========================================
    SIMPLE FADE ANIMATION
==========================================*/

.card,
.item,
.about img,
.right,
.cta{
    animation:fadeUp .8s ease;
}

@keyframes fadeUp{

    from{
        opacity:0;
        transform:translateY(40px);
    }

    to{
        opacity:1;
        transform:translateY(0);
    }

}

/*==========================================
    RESPONSIVE
==========================================*/

@media(max-width:1100px){

.about{
    grid-template-columns:1fr;
}


.gallery{
    grid-template-columns:repeat(2,1fr);
}

}

@media(max-width:768px){

/* header stacking is handled by the 992px slide-out panel — do NOT stack here */

.buttons{
    flex-direction:column;
    align-items:center;
    gap:14px;
}

.primary-btn,
.secondary-btn{
    width:100%;
    max-width:280px;
    text-align:center;
}


.gallery{
    grid-template-columns:1fr;
}

.stats{
    flex-direction:column;
    gap:25px;
}

section h2{
    font-size:45px;
}

.right h2{
    font-size:45px;
    line-height:50px;
}

.cta h2{
    font-size:42px;
}

}

@media(max-width:500px){

header{
    padding:16px 5%;
}

section{
    padding:70px 20px;
}

.logo h2{
    font-size:30px;
}

.buttons{
    flex-direction:column;
    align-items:center;
    gap:12px;
    margin-top:30px;
}

.primary-btn,
.secondary-btn{
    width:100%;
    max-width:260px;
    text-align:center;
    padding:13px 30px;
}

.btn{
    width:auto;
}

.item img{
    height:250px;
}

footer h2{
    font-size:34px;
}

}

/* ===== JAVASCRIPT SUPPORT ===== */

nav ul li a.active{
    color:var(--gold);
}

#progress-bar{
    position:fixed;
    top:0;
    left:0;
    width:0%;
    height:4px;
    background:var(--gold);
    z-index:9999;
    transition:.15s linear;
}

#topBtn{
    position:fixed;
    right:25px;
    bottom:25px;
    width:50px;
    height:50px;
    border:none;
    border-radius:50%;
    background:var(--gold);
    color:#000;
    font-size:22px;
    cursor:pointer;
    opacity:0;
    visibility:hidden;
    transition:.35s;
    z-index:999;
}

#topBtn.show{
    opacity:1;
    visibility:visible;
}

.visible{
    opacity:1 !important;
    transform:translateY(0) !important;
}

/*==========================
CUSTOM CURSOR
==========================*/

.custom-cursor{

position:fixed;

width:18px;
height:18px;

border:2px solid var(--gold);

border-radius:50%;

pointer-events:none;

transform:translate(-50%,-50%);

transition:.15s;

z-index:999999;

}

.cursor-grow{

width:45px;
height:45px;

background:rgba(212,175,55,.15);

}

/*==========================
PRELOADER
==========================*/

.preloader{

position:fixed;

inset:0;

background:#000;

display:flex;

justify-content:center;

align-items:center;

z-index:999999;

transition:.7s;

}

.preloader.hide{

opacity:0;

visibility:hidden;

}

/*==========================
SHOW ANIMATION
==========================*/

.card,
.item,
.about,
.services,
.portfolio,
.cta{

opacity:0;

transform:translateY(60px);

transition:.8s;

}

.show{

opacity:1;

transform:translateY(0);

}

/*==========================================
NEW HERO
==========================================*/

.scroll-down{

position:absolute;

bottom:35px;

left:50%;

transform:translateX(-50%);

}

.scroll-down span{

display:block;

width:28px;

height:45px;

border:2px solid white;

border-radius:20px;

position:relative;

}

.scroll-down span::before{

content:"";

position:absolute;

left:50%;

top:8px;

transform:translateX(-50%);

width:5px;

height:10px;

background:white;

border-radius:10px;

animation:scroll 1.5s infinite;

}

@keyframes scroll{

0%{

opacity:1;

transform:translate(-50%,0);

}

100%{

opacity:0;

transform:translate(-50%,18px);

}

}


/*=========================================================
    ABOUT PAGE
=========================================================*/

/*================ PAGE BANNER ================*/

.page-banner{

    position:relative;

    height:60vh;

    display:flex;

    justify-content:center;

    align-items:center;

    text-align:center;

    background-size:cover;

    background-position:center;

    background-attachment:fixed;

    overflow:hidden;

}

.about-banner{

    background:
    linear-gradient(rgba(0,0,0,.65),rgba(0,0,0,.75)),
    url("images/hero.jpg");

    background-size:cover;

    background-position:center;

}

.banner-content{

    position:relative;

    z-index:2;

    color:#fff;

}

.banner-content p{

    color:var(--gold);

    letter-spacing:4px;

    font-size:14px;

    margin-bottom:18px;

}

.banner-content h1{

    font-size:80px;

    margin-bottom:15px;

    font-family:'Bebas Neue',sans-serif;

    letter-spacing:3px;

}

.banner-content span{

    color:#d5d5d5;

    font-size:18px;

}

/*================ STORY SECTION ================*/

.about-story{

    display:grid;

    grid-template-columns:1fr 1fr;

    align-items:center;

    gap:80px;

    padding:120px 8%;

    background:#0a0a0a;

}

.story-image{

    overflow:hidden;

    border-radius:15px;

}

.story-image img{

    width:100%;

    display:block;

    transition:.6s;

}

.story-image:hover img{

    transform:scale(1.08);

