    p:not(header *):not(.hero *):not(.studio-section *){

        font-size:15px !important;

        line-height:1.8;

    }

    .banner-content{

        padding:0 20px;

    }

}

/*================ SMALL MOBILE =================*/

@media (max-width:480px){

    h1:not(header *):not(.hero *):not(.studio-section *){

        font-size:34px !important;

    }

    h2:not(header *):not(.hero *):not(.studio-section *){

        font-size:28px !important;

    }

    .primary-btn{

        width:100%;

        text-align:center;

    }

}

/* Reduced motion keeps content visible without entrance or decorative movement. */
@media(prefers-reduced-motion:reduce){
    .showcase-frame,.showcase-disclosure summary svg,
    .services [data-service-showcase] .studio-card-image::after{transition:none;}
    .showcase-disclosure[open] .showcase-detail{animation:none;}
    .services [data-service-showcase]:hover .showcase-frame,
    .services [data-service-showcase]:has(details[open]) .showcase-frame{transform:none;}
    html{scroll-behavior:auto;}
    header,nav,nav ul li,.nav-overlay,.menu-toggle span,
    .btn,.primary-btn,.secondary-btn,.text-link,.studio-card,
    .enquiry-button,.enquiry-field input,.enquiry-field select,.enquiry-field textarea{transition:none;}
    .card,.item,.about img,.right,.cta,.scroll-down span::before{animation:none;}
    .card,.item,.about,.services,.portfolio,.cta{opacity:1; transform:none; transition:none;}
    .item:hover img{transform:none; transition:none;}
    .item img{transition:none;}
    .primary-btn:hover,.card:hover{transform:none;}
    .custom-cursor{display:none;}
}
